(function () {
  const $ = selector => document.querySelector(selector);
  if (!$("#armourFitGate")) return;
  const key = "atlas-armour-fit-v1";
  const profiles = ["small", "large"];
  const zones = ["left", "chest", "right"];
  const poses = ["near", "centre", "left30", "right30", "far"];
  let state = { people: { small: { height: 150, chest: 78, shoulder: 36, checks: [] }, large: { height: 190, chest: 118, shoulder: 52, checks: [] } }, coverage: [] };
  try { state = { ...state, ...JSON.parse(localStorage.getItem(key) || "{}") }; } catch {}
  const lang = () => localStorage.getItem("atlas-language") === "en" ? "en" : "vi";
  const copy = {
    vi: { label: "GIÁP DÙNG CHUNG / FIT + COVERAGE", title: "Chứng minh một áo dùng được cho Hero và Boss", status: n => `${n} / 2 GATES PASS`, profileNames: ["Người nhỏ nhất dự kiến", "Người lớn nhất dự kiến"], fields: ["Chiều cao (cm)", "Vòng ngực (cm)", "Ngang vai (cm)"], checks: ["Không cấn cạnh cứng", "Tự mở quick-release được", "Thoải mái sau 5 phút", "Ba receiver không bị che"], panel: "front panel mock-up", adjust: "minimum strap adjustment", fitRule: "FIT PASS cần hai người thật ở hai đầu dải kích thước và đủ 4 kiểm tra mỗi người.", fitPass: "FIT PASS · hai biên kích thước đã được chứng minh", coverageEyebrow: "15 PHÁT BẮN THẬT / ÁNH SÁNG SỰ KIỆN", coverageTitle: "Ma trận che phủ receiver", zoneNames: ["VAI TRÁI", "NGỰC", "VAI PHẢI"], poseNames: ["1 m thẳng", "3 m thẳng", "3 m trái 30°", "3 m phải 30°", "5 m thẳng"], coverageRule: n => `COVERAGE BLOCKED · ${n}/15 ô PASS. Thực hiện tại ánh sáng hội chợ dự kiến.`, coveragePass: "COVERAGE PASS · 15/15 phát được receiver đúng vùng xác nhận", export: "Tải fit + coverage JSON" },
    en: { label: "SHARED ARMOUR / FIT + COVERAGE", title: "Prove one garment works for Hero and Boss", status: n => `${n} / 2 GATES PASS`, profileNames: ["Expected smallest wearer", "Expected largest wearer"], fields: ["Height (cm)", "Chest (cm)", "Shoulder (cm)"], checks: ["No hard-edge pressure", "Can reach quick release", "Comfortable after 5 minutes", "All three receivers stay exposed"], panel: "front panel mock-up", adjust: "minimum strap adjustment", fitRule: "FIT PASS requires two real people at both size boundaries and all four checks for each.", fitPass: "FIT PASS · both size boundaries proven", coverageEyebrow: "15 REAL SHOTS / EVENT LIGHT", coverageTitle: "Receiver coverage matrix", zoneNames: ["LEFT", "CHEST", "RIGHT"], poseNames: ["1 m centre", "3 m centre", "3 m left 30°", "3 m right 30°", "5 m centre"], coverageRule: n => `COVERAGE BLOCKED · ${n}/15 cells PASS. Test under expected event light.`, coveragePass: "COVERAGE PASS · 15/15 shots confirmed the correct receiver zone", export: "Download fit + coverage JSON" }
  };
  const save = () => localStorage.setItem(key, JSON.stringify(state));
  const clamp = (value,min,max) => Math.max(min,Math.min(max,value));
  const fitPass = () => profiles.every(profile => state.people[profile].checks.length === 4);
  const coveragePass = () => state.coverage.length === zones.length * poses.length;
  function render() {
    const t = copy[lang()]; const passed = Number(fitPass()) + Number(coveragePass()); const small = state.people.small; const large = state.people.large; const panelWidth = Math.round(clamp(small.shoulder * .92, 34, 46)); const adjustRange = Math.round(Math.max(20, large.chest - small.chest + 10));
    $("#armourFitLabel").textContent = t.label; $("#armourFitTitle").textContent = t.title; $("#armourFitStatus").textContent = t.status(passed); $("#fitPanelWidth").textContent = `${panelWidth} cm`; $("#fitPanelWidthLabel").textContent = t.panel; $("#fitAdjustRange").textContent = `≥ ${adjustRange} cm`; $("#fitAdjustRangeLabel").textContent = t.adjust;
    $("#wearerProfiles").innerHTML = profiles.map((profile,index) => { const person = state.people[profile]; return `<article class="wearer-card"><h4>${t.profileNames[index]}</h4><div class="wearer-fields">${["height","chest","shoulder"].map((field,fieldIndex) => `<label><span>${t.fields[fieldIndex]}</span><input type="number" min="30" max="250" value="${person[field]}" data-wearer="${profile}" data-measure="${field}"></label>`).join("")}</div><div class="wearer-checks">${t.checks.map((check,checkIndex) => `<label><input type="checkbox" data-wearer-check="${profile}" data-check-index="${checkIndex}" ${person.checks.includes(checkIndex) ? "checked" : ""}><span>${check}</span></label>`).join("")}</div></article>`; }).join("");
    const fit = $("#fitAcceptance"); fit.classList.toggle("is-pass",fitPass()); fit.textContent = fitPass() ? t.fitPass : t.fitRule;
    $("#coverageEyebrow").textContent = t.coverageEyebrow; $("#coverageTitle").textContent = t.coverageTitle;
    $("#coverageMatrix").innerHTML = `<span></span>${t.zoneNames.map(name => `<span class="matrix-head">${name}</span>`).join("")}${poses.map((pose,poseIndex) => `<span class="matrix-row">${t.poseNames[poseIndex]}</span>${zones.map(zone => { const id = `${zone}:${pose}`; return `<button type="button" data-coverage-cell="${id}" class="${state.coverage.includes(id) ? "is-pass" : ""}">${state.coverage.includes(id) ? "PASS" : "WAIT"}</button>`; }).join("")}`).join("")}`;
    const coverage = $("#coverageVerdict"); coverage.classList.toggle("is-pass",coveragePass()); coverage.textContent = coveragePass() ? t.coveragePass : t.coverageRule(state.coverage.length); $("#exportFitEvidence").textContent = t.export;
    if (fitPass() && coveragePass()) window.dispatchEvent(new CustomEvent("atlas-journey-complete", { detail: { step: "fit" } }));
  }
  $("#wearerProfiles").addEventListener("change", event => { const input = event.target; if (input.matches("[data-measure]")) state.people[input.dataset.wearer][input.dataset.measure] = Number(input.value); else if (input.matches("[data-wearer-check]")) { const person = state.people[input.dataset.wearer]; const index = Number(input.dataset.checkIndex); person.checks = input.checked ? [...new Set([...person.checks,index])] : person.checks.filter(item => item !== index); } save(); render(); });
  $("#coverageMatrix").addEventListener("click", event => { const button = event.target.closest("[data-coverage-cell]"); if (!button) return; const id = button.dataset.coverageCell; state.coverage = state.coverage.includes(id) ? state.coverage.filter(item => item !== id) : [...state.coverage,id]; save(); render(); });
  $("#exportFitEvidence").addEventListener("click", () => { const payload = { schema: "atlas-armour-fit-evidence/v1", generatedAt: new Date().toISOString(), physicalProof: fitPass() && coveragePass(), people: state.people, coverage: state.coverage, coverageProtocol: { zones, poses, required: 15, lighting: "actual-event-light" } }; const blob = new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}); const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = "atlas-armour-fit-coverage.json"; link.click(); URL.revokeObjectURL(link.href); });
  window.addEventListener("atlas-language-change",render); render();
})();
